const $ = (sel) => document.querySelector(sel);

const examples = [
  "Θρέϊξ",
  "Θρῆϊξ",
  "Θρῇξ",
  "σάλπιγξ",
  "σύριγξ",
  "μῆνιγξ",
  "ὄρνιξ",
  "κῆρυξ",
  "Κῆϋξ",
  "Βέβρυξ",
  "βόμβυξ",
  "Σάμβυξ",
  "Ἄμπυξ",
  "κάλυξ",
  "ψάλυξ",
  "πολυᾶϊξ",
  "κορυθᾶϊξ"
];

// --- Greek helpers (very lightweight) ---
const COMBINING = /[\u0300-\u036f]/g;

function nfd(s){ return (s||"").normalize("NFD"); }
function nfc(s){ return (s||"").normalize("NFC"); }

function stripCombining(s){ return nfd(s).replace(COMBINING, "").normalize("NFC"); }

function hasAccent(s){
  const d = nfd(s);
  return /[\u0301\u0342\u0300]/.test(d); // acute, circumflex, grave
}

function lastLettersBase(s, n){
  const base = stripCombining(s).replace(/\s+/g, "");
  return base.slice(-n);
}

function detectEnding(word){
  const w = stripCombining(word).replace(/\s+/g, "");
  const lower = w.toLowerCase();
  if (lower.endsWith("ιγξ")) return "-ιγξ";
  if (lower.endsWith("ιξ")) return "-ιξ";
  if (lower.endsWith("υξ")) return "-υξ";
  return null;
}

function guessInclusive(word){
  // Totally playful: if it looks like a container/tool (ends -θηκη, -δοχη, -φυλαξ etc.) or contains "καλυ" etc.
  const base = stripCombining(word).toLowerCase();
  const hints = ["θηκ", "δοχ", "καλυ", "κυλ", "αμπυ", "σαμβυ", "βομβυ"]; // silly
  return hints.some(h => base.includes(h));
}

function suggestAccentTendency(word, inclusiveMode){
  const ending = detectEnding(word);
  if (!ending) return {ending:null, tendency:"unknown", note:"Ending not recognized (try -ιξ, -ιγξ, -υξ)."};

  if (ending === "-υξ"){
    let inclusive;
    if (inclusiveMode === "yes") inclusive = true;
    else if (inclusiveMode === "no") inclusive = false;
    else inclusive = guessInclusive(word);

    if (!inclusive){
      return {ending, tendency:"barytone", note:"Herodian: words in -υξ are barytone (accent not on the last syllable), unless ‘inclusive’."};
    } else {
      return {ending, tendency:"exception (inclusive)", note:"Inclusive sense selected/guessed → may escape the default barytone rule."};
    }
  }

  // For -ιξ / -ιγξ Herodian lists many; accent varies. We'll just say “often oxytone in lists, but not guaranteed”.
  return {ending, tendency:"varies", note:"-ιξ / -ιγξ words show mixed accentuation in practice; Herodian is cataloguing forms."};
}

// Synaloepha toy: contract diaeresis-iota + vowel into long diphthong-ish spellings.
function synaloepha(word){
  // Work in NFC for nicer output, but match both precomposed and decomposed.
  let s = nfc(word);

  // Normalize common sequences: (ε/η/α/ο/ω) + ϊ/ΐ + ξ/γξ etc.
  // We'll do a few targeted replacements inspired by Θρέϊξ → Θρῇξ.
  // Replace: εϊ -> ῃ ; ηϊ -> ῃ ; αϊ -> ᾳ ; οϊ -> ῳ ; ωϊ -> ῳ
  // Also with tonos on iota: εΐ etc.
  const reps = [
    [/ε[ϊΐ]/g, "ῃ"],
    [/η[ϊΐ]/g, "ῃ"],
    [/α[ϊΐ]/g, "ᾳ"],
    [/ο[ϊΐ]/g, "ῳ"],
    [/ω[ϊΐ]/g, "ῳ"],
    [/Ε[ϊΐ]/g, "ῌ"],
    [/Η[ϊΐ]/g, "ῌ"],
    [/Α[ϊΐ]/g, "ᾼ"],
    [/Ο[ϊΐ]/g, "ῼ"],
    [/Ω[ϊΐ]/g, "ῼ"],
  ];

  let out = s;
  reps.forEach(([re, to]) => out = out.replace(re, to));

  // If nothing changed, try decomposed patterns (vowel + combining diaeresis on iota)
  if (out === s){
    const d = nfd(word);
    // iota with diaeresis: ι + \u0308 ; with tonos: \u0301
    const iDia = "ι\u0308(?:\u0301)?";
    const map = [
      [new RegExp("ε"+iDia, "g"), "ῃ"],
      [new RegExp("η"+iDia, "g"), "ῃ"],
      [new RegExp("α"+iDia, "g"), "ᾳ"],
      [new RegExp("ο"+iDia, "g"), "ῳ"],
      [new RegExp("ω"+iDia, "g"), "ῳ"],
    ];
    let dd = d;
    map.forEach(([re,to]) => dd = dd.replace(re,to));
    out = nfc(dd);
  }

  return out;
}

function makeWord(stem){
  const clean = (stem||"").trim();
  if (!clean) return null;
  const endings = ["ιξ","ιγξ","υξ"];
  const end = endings[Math.floor(Math.random()*endings.length)];
  // If stem ends with a vowel, just append; else add a connecting vowel sometimes.
  const base = stripCombining(clean);
  const last = base.slice(-1).toLowerCase();
  const vowels = "αεηιουω";
  let connector = "";
  if (!vowels.includes(last) && Math.random() < 0.45) connector = "ι";
  return clean + connector + end;
}

function badge(text, kind){
  return `<span class="badge ${kind}">${text}</span>`;
}

function render(){
  const word = $("#inWord").value.trim();
  const mode = $("#mode").value;
  const inclusiveMode = $("#inclusive").value;
  const out = $("#out");

  if (!word){
    out.innerHTML = `<div class="small">Type something like <code class="inline">Θρέϊξ</code>, <code class="inline">σάλπιγξ</code>, <code class="inline">κῆρυξ</code>, <code class="inline">Βέβρυξ</code>.</div>`;
    return;
  }

  if (mode === "synaloepha"){
    const contracted = synaloepha(word);
    const changed = contracted !== nfc(word);
    out.innerHTML = `
      <div class="kv"><div class="k">Input</div><div class="v">${escapeHtml(word)}</div></div>
      <div class="kv"><div class="k">After “synaloepha”</div><div class="v">${escapeHtml(contracted)} ${changed ? badge("contracted","good") : badge("no change","warn")}</div></div>
      <hr class="sep"/>
      <div class="small">Rule of thumb used here: <code class="inline">εϊ/ηϊ → ῃ</code>, <code class="inline">αϊ → ᾳ</code>, <code class="inline">οϊ/ωϊ → ῳ</code> (very simplified). Try <code class="inline">Θρέϊξ</code> → <code class="inline">Θρῇξ</code>.</div>
    `;
    return;
  }

  if (mode === "make"){
    const made = makeWord(word);
    const info = suggestAccentTendency(made, inclusiveMode);
    out.innerHTML = `
      <div class="kv"><div class="k">Stem</div><div class="v">${escapeHtml(word)}</div></div>
      <div class="kv"><div class="k">New word</div><div class="v">${escapeHtml(made)} ${badge(info.ending || "?","warn")}</div></div>
      <div class="kv"><div class="k">Accent tendency</div><div class="v">${escapeHtml(info.tendency)}</div></div>
      <div class="small">${escapeHtml(info.note)}</div>
    `;
    return;
  }

  // analyze
  const ending = detectEnding(word);
  const info = suggestAccentTendency(word, inclusiveMode);
  const accented = hasAccent(word);
  const base = stripCombining(word);

  let kind = "warn";
  if (info.tendency === "barytone") kind = "good";
  if (info.tendency === "unknown") kind = "bad";

  out.innerHTML = `
    <div class="kv"><div class="k">Word (as typed)</div><div class="v">${escapeHtml(word)} ${accented ? badge("has accent mark","good") : badge("no accent mark","warn")}</div></div>
    <div class="kv"><div class="k">Base letters</div><div class="v">${escapeHtml(base)}</div></div>
    <div class="kv"><div class="k">Detected ending</div><div class="v">${escapeHtml(ending || "(none)")} ${badge(info.tendency, kind)}</div></div>
    <div class="small">${escapeHtml(info.note)}</div>
    <hr class="sep"/>
    <div class="small">Tip: switch to <b>Synaloepha</b> mode and try forms with <span class="gk">ϊ</span>/<span class="gk">ΐ</span> (e.g. <code class="inline">Θρέϊξ</code>).</div>
  `;
}

function escapeHtml(s){
  return (s+"")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#39;");
}

$("#btnRun").addEventListener("click", render);
$("#btnClear").addEventListener("click", () => { $("#inWord").value = ""; render(); });
$("#btnRandom").addEventListener("click", () => {
  $("#inWord").value = examples[Math.floor(Math.random()*examples.length)];
  render();
});
$("#inWord").addEventListener("input", () => {
  // light debounce
  window.clearTimeout(window.__t);
  window.__t = window.setTimeout(render, 120);
});
$("#mode").addEventListener("change", render);
$("#inclusive").addEventListener("change", render);

// initial
render();

