      <div class="kv"><div class="k">Stem</div><div class="v">${escapeHtml(word)}</div></div>
      <div class="kv"><div class="k">New word</div><div class="v">${escapeHtml(made)} ${badge(info.ending || "?","warn")}</div></div>
      <div class="kv"><div class="k">Accent tendency</div><div class="v">${escapeHtml(info.tendency)}</div></div>
      <div class="small">${escapeHtml(info.note)}</div>
    `;
    return;
  }

  // analyze
  const ending = detectEnding(word);
  const info = suggestAccentTendency(word, inclusiveMode);
  const accented = hasAccent(word);
  const base = stripCombining(word);

  let kind = "warn";
  if (info.tendency === "barytone") kind = "good";
  if (info.tendency === "unknown") kind = "bad";

  out.innerHTML = `
    <div class="kv"><div class="k">Word (as typed)</div><div class="v">${escapeHtml(word)} ${accented ? badge("has accent mark","good") : badge("no accent mark","warn")}</div></div>
    <div class="kv"><div class="k">Base letters</div><div class="v">${escapeHtml(base)}</div></div>
    <div class="kv"><div class="k">Detected ending</div><div class="v">${escapeHtml(ending || "(none)")} ${badge(info.tendency, kind)}</div></div>
    <div class="small">${escapeHtml(info.note)}</div>
    <hr class="sep"/>
    <div class="small">Tip: switch to <b>Synaloepha</b> mode and try forms with <span class="gk">ϊ</span>/<span class="gk">ΐ</span> (e.g. <code class="inline">Θρέϊξ</code>).</div>
  `;
}

function escapeHtml(s){
  return (s+"")
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#39;");
}

